'use strict';

// MODULES //

var base = require( './base.js' );


// MAIN //

/**
* Returns the value of the one-norm, Frobenius norm, infinity-norm, or the largest absolute value of any element of a real symmetric matrix `AP` supplied in packed form using alternative indexing semantics.
*
* @param {string} order - storage layout ('row-major' or 'column-major')
* @param {string} norm - specifies the norm type
* @param {string} uplo - specifies whether the upper or lower triangular part of `A` is referenced ('upper' or 'lower')
* @param {NonNegativeInteger} N - order of the matrix `A`
* @param {Float64Array} AP - packed form of a symmetric matrix `A`
* @param {integer} strideAP - `AP` stride length
* @param {NonNegativeInteger} offsetAP - starting `AP` index
* @returns {number} matrix norm
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* // AP = [ 1.0, 2.0, 5.0 ] (2x2 symmetric packed column-major upper)
* var AP = new Float64Array( [ 1.0, 2.0, 5.0 ] );
*
* var norm = dlansp( 'column-major', 'M', 'upper', 2, AP, 1, 0 );
* // returns 5.0
*/
function dlansp( order, norm, uplo, N, AP, strideAP, offsetAP ) {
	return base( order, norm, uplo, N, AP, strideAP, offsetAP );
}


// EXPORTS //

module.exports = dlansp;
